import io, json, math, subprocess
from PIL import Image, ImageDraw, ImageFont
import numpy as np


def adapt(path):
    duration = 0.0
    fps = 25.0
    try:
        p = subprocess.run(['ffprobe', '-v', 'error', '-select_streams', 'v:0', '-show_entries', 'stream=duration,avg_frame_rate:format=duration', '-of', 'json', path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=8)
        info = json.loads(p.stdout or b'{}')
        stream = (info.get('streams') or [{}])[0]
        for v in (stream.get('duration'), info.get('format', {}).get('duration')):
            try:
                d = float(v)
                if math.isfinite(d) and d > 0:
                    duration = d
                    break
            except Exception:
                pass
        try:
            a, b = stream.get('avg_frame_rate', '25/1').split('/')
            fps = float(a) / float(b)
            if not math.isfinite(fps) or fps <= 0:
                fps = 25.0
        except Exception:
            pass
    except Exception:
        pass

    def frame(t):
        try:
            p = subprocess.run(['ffmpeg', '-v', 'error', '-ss', '%.4f' % max(0, t), '-i', path, '-frames:v', '1', '-vf', 'scale=320:240:force_original_aspect_ratio=decrease', '-f', 'image2pipe', '-vcodec', 'mjpeg', 'pipe:1'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5)
            if p.stdout:
                im = Image.open(io.BytesIO(p.stdout))
                im.load()
                return im.convert('RGB')
        except Exception:
            pass
        return None

    if duration <= 0:
        try:
            import adapter_kit
            frames = adapter_kit.video_frames(path, n=12)
            if frames:
                return {'images': [x.convert('RGB') for x in frames[:9]]}
        except Exception:
            pass
        im = frame(0)
        return {'images': [im] if im else []}

    end = max(0.0, duration - max(1.0 / fps, 0.04))
    count = 18 if duration > 1 else 12
    times = [end * i / (count - 1) for i in range(count)]
    samples = []
    for t in times:
        im = frame(t)
        if im is not None:
            samples.append((t, im))
    if not samples:
        try:
            import adapter_kit
            return {'images': adapter_kit.video_frames(path, n=6)[:9]}
        except Exception:
            return {'images': []}

    # Add intermediate frames in intervals with the largest visual changes.
    if len(samples) >= 2:
        scores = []
        for i in range(len(samples) - 1):
            a = np.asarray(samples[i][1].convert('L').resize ( (64, 48) ), dtype=np.float32)
            b = np.asarray(samples[i + 1][1].convert('L').resize((64, 48)), dtype=np.float32)
            scores.append((float(np.mean(np.abs(a - b))), i))
        for _, i in sorted(scores, reverse=True)[:6]:
            t = (samples[i][0] + samples[i + 1][0]) / 2
            im = frame(t)
            if im is not None:
                samples.append((t, im))
    samples.sort(key=lambda x: x[0])

    # Four frames per sheet preserve useful detail under the 512-pixel limit.
    sheets = []
    for start in range(0, len(samples), 4):
        group = samples[start:start + 4]
        sheet = Image.new('RGB', (512, 430), 'white')
        draw = ImageDraw.Draw(sheet)
        draw.text((5, 3), 'Duration %.2f s | frames %d-%d' % (duration, start + 1, start + len(group)), fill='black')
        for j, (t, im) in enumerate(group):
            x = (j % 2) * 256
            y = 22 + (j // 2) * 204
            im.thumbnail((252, 180), Image.Resampling.LANCZOS)
            sheet.paste(im, (x + (256 - im.width) // 2, y + (180 - im.height) // 2))
            draw.text((x + 5, y + 182), '%.2f s' % t, fill='black')
        sheets.append(sheet)
    return {'images': sheets[:9]}
